//! Strict deterministic scenario answer assertions and lifecycle evidence checks.
use crate::{Result,canonical::{canonical,digest,sha256}};
use serde_json::{Value,json};
use std::collections::{BTreeMap,BTreeSet};
fn arr(v:&Value)->&[Value]{v.as_array().map(Vec::as_slice).unwrap_or(&[])}
fn text<'a>(v:&'a Value,k:&str)->&'a str{v[k].as_str().unwrap_or("")}
fn truth(v:&Value)->bool{match v{Value::Null=>false,Value::Bool(v)=>*v,Value::String(s)=>!s.is_empty(),Value::Array(a)=>!a.is_empty(),Value::Object(o)=>!o.is_empty(),Value::Number(n)=>n.as_f64()!=Some(0.)}}
fn string_set(v:&Value)->BTreeSet<String>{arr(v).iter().filter_map(|v|v.as_str().map(str::to_string)).collect()}
fn sha(v:&Value)->bool{v.as_str().is_some_and(|s|s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)))}
pub fn answer_json(output:&str,locator:&str)->Result<Value>{if locator=="whole_output_json"{return crate::strict_json::parse(output.as_bytes()).map_err(|e|format!("candidate answer: {e}").into())}let r=regex::Regex::new(r"(?s)<FINAL_JSON>\s*(.*?)\s*</FINAL_JSON>").unwrap();let matches=r.captures_iter(output).collect::<Vec<_>>();if matches.len()!=1{return Err("candidate must contain exactly one FINAL_JSON block".into())}crate::strict_json::parse(matches[0][1].as_bytes()).map_err(|e|format!("candidate FINAL_JSON: {e}").into())}
fn pointer<'a>(answer:&'a Value,pointer:&str)->Option<&'a Value>{if pointer.is_empty(){return Some(answer)}let mut value=answer;for raw in pointer.get(1..)?.split('/'){let key=raw.replace("~1","/").replace("~0","~");value=if value.is_object(){value.get(&key)?}else if value.is_array()&&!key.is_empty()&&key.bytes().all(|b|b.is_ascii_digit()){value.get(key.parse::<usize>().ok()?)?}else{return None};}Some(value)}
fn same_type(a:&Value,b:&Value)->bool{match(a,b){(Value::Number(a),Value::Number(b))=>a.is_f64()==b.is_f64(),_=>std::mem::discriminant(a)==std::mem::discriminant(b)}}
fn assertion(a:&Value,answer:&Value,output:&str)->Result<(bool,&'static str,Value)>{let kind=text(a,"kind");let expected=&a["expected"];if kind.starts_with("text_"){let passed=arr(expected).iter().all(|v|v.as_str().is_some_and(|s|if kind=="text_contains_all"{output.contains(s)}else{!output.contains(s)}));return Ok((passed,if passed{"matched"}else{"text_mismatch"},json!(output)))}let Some(actual)=pointer(answer,text(a,"path"))else{return Ok((false,"json_path_missing",Value::Null))};let expected_set=arr(expected).iter().map(canonical).collect::<BTreeSet<_>>();let actual_set=arr(actual).iter().map(canonical).collect::<BTreeSet<_>>();let passed=match kind{"json_equals"=>actual==expected&&same_type(actual,expected),"json_number"=>actual.as_f64().zip(expected.as_f64()).is_some_and(|(actual,expected)|actual.is_finite()&&(actual-expected).abs()<=a["absolute_tolerance"].as_f64().unwrap_or(0.).max(a["relative_tolerance"].as_f64().unwrap_or(0.)*actual.abs().max(expected.abs()))),"json_set_equals"=>actual.is_array()&&actual_set==expected_set,"json_contains_all"|"json_excludes_all"=>{let contains=kind=="json_contains_all";if actual.is_array(){if contains{expected_set.is_subset(&actual_set)}else{expected_set.is_disjoint(&actual_set)}}else if let Some(s)=actual.as_str(){arr(expected).iter().all(|v|v.as_str().is_some_and(|needle|s.contains(needle)==contains))}else{false}},"json_keys_equals"=>actual.as_object().is_some_and(|m|m.keys().cloned().collect::<BTreeSet<_>>()==string_set(expected)),"json_nonempty_string"=>actual.as_str().is_some_and(|s|s.trim().chars().count()as u64>=expected.as_u64().unwrap_or(u64::MAX)),_=>return Err(format!("unsupported assertion kind {kind}").into())};Ok((passed,if passed{"matched"}else{"value_mismatch"},actual.clone()))}
pub fn self_assessment(answer:&Value,output:&str)->bool{fn reserved(v:&Value)->bool{match v{Value::Object(m)=>m.iter().any(|(k,v)|["score","scores","passed","pass","candidate_scores","hard_gates","hard_violations","judge_score","evaluation_score","suite_score","golden_passed"].contains(&k.to_lowercase().as_str())||reserved(v)),Value::Array(a)=>a.iter().any(reserved),_=>false}}reserved(answer)||regex::Regex::new(r"(?i)(?:judge|evaluation|eval|自评|评分)\s*(?:score|得分|分数)?\s*[:=]\s*\d{1,3}").unwrap().is_match(output)}
pub fn canonical_delegation(s:&Value)->Option<Value>{s["canonical_delegation"].is_object().then(||json!({"tasks":s["canonical_delegation"]["tasks"],"max_concurrency":s["canonical_delegation"]["max_concurrency"]}))}
pub fn candidate_prompt(s:&Value)->String{let mut sections=vec![text(s,"prompt").to_string()];if let Some(args)=canonical_delegation(s){sections.push(format!("EVAL-ONLY HOST DELEGATION OBJECT\nFor this acceptance run, call spawn_subagent exactly once using the following JSON object as its entire arguments object. Preserve every task prompt, description, identity, array order, and max_concurrency exactly; do not add fields or instructions.\n{}",canonical(&args)));}sections.push("HOST OUTPUT CONFORMANCE\nFollow the task's OUTPUT CONTRACT literally. Emit exactly one <FINAL_JSON> object and never wrap it in a Markdown fence. If the task explicitly requests a memo before the block, keep it concise; otherwise emit no prose outside the block. Keep literal enum tokens, IDs, scalar types, and exact arrays as specified; do not replace them with explanatory objects or synonyms. Do not call parent tools other than the one host delegation call above.".into());if let Some(hints)=s["output_conformance_hints"].as_array().filter(|a|!a.is_empty()){sections.push(format!("HOST-SPECIFIED OUTPUT LITERALS\n{}",hints.iter().map(|h|format!("- {}",h.as_str().unwrap_or(""))).collect::<Vec<_>>().join("\n")));}sections.join("\n\n")}
pub fn validated_trial(scenario:&Value,observation:&Value)->Result<Value>{let output=text(observation,"candidate_output");let(answer,parse_error)=match answer_json(output,scenario["answer_locator"].as_str().unwrap_or("final_json_tag")){Ok(v)=>(v,None),Err(e)=>(Value::Null,Some(e.to_string()))};let assessment=self_assessment(&answer,output);let mut assertions=vec![];for a in arr(&scenario["expected_assertions"]){let(passed,reason,actual)=if parse_error.is_some()&&!text(a,"kind").starts_with("text_"){(false,"answer_json_invalid",Value::Null)}else{assertion(a,&answer,output)?};assertions.push(json!({"assertion_id":a["assertion_id"],"kind":a["kind"],"passed":passed,"reason":reason,"expected_sha256":digest(&a["expected"]),"actual_sha256":digest(&actual)}));}let checks=execution_checks(scenario,observation);let golden=assertions.iter().all(|a|a["passed"]==true);let execution=checks.iter().all(|a|a["passed"]==true);Ok(json!({"scenario_id":scenario["scenario_id"],"trial":observation["trial"],"observation_sha256":observation["observation_sha256"],"answer_parse_error":parse_error,"candidate_self_assessment_detected":assessment,"assertions":assertions,"execution_checks":checks,"golden_passed":golden,"execution_checks_passed":execution,"trial_accepted":golden&&execution&&!assessment}))}
fn identity(item:&Value)->String{let profile=text(item,"profile_id");if !profile.is_empty(){profile.into()}else{let kind=text(item,"agent_type");if kind.is_empty(){String::new()}else{format!("builtin:{kind}")}}}
fn call_id(item:&Value)->String{["tool_call_id","call_id","tool_id"].iter().find_map(|k|item[k].as_str().filter(|s|!s.is_empty())).unwrap_or("").into()}
fn tool_name(item:&Value)->String{["name","tool_name"].iter().find_map(|k|item[k].as_str().filter(|s|!s.is_empty())).unwrap_or("").into()}
fn aliases(item:&Value,fields:&[&str])->bool{let values=fields.iter().filter_map(|k|item[k].as_str().filter(|s|!s.is_empty())).collect::<BTreeSet<_>>();values.len()==1}
fn no_error(v:&Value)->bool{!truth(&v["error"])&&(v["error_code"].is_null()||v["error_code"]=="")}
fn normalized_delegation(v:&Value)->Option<Value>{let m=v.as_object()?;if m.keys().any(|k|!["tasks","max_concurrency","description"].contains(&k.as_str())){return None}Some(json!({"tasks":v["tasks"],"max_concurrency":v["max_concurrency"]}))}
pub fn execution_checks(s:&Value,o:&Value)->Vec<Value>{let profiles=arr(&s["required_agent_ids"]);let records=|key:&str|arr(&o[key]).iter().filter(|v|v.is_object()).collect::<Vec<_>>();let starts=records("subagent_starts");let finishes=records("subagent_finishes");let terminals=records("terminal_events");let overlaps=records("parallel_overlaps");let tool_starts=records("tool_starts");let tool_results=records("tool_results");let text_events=records("text_events");let attempts=arr(&o["attempt_ids"]).iter().filter_map(|v|v.as_str().filter(|s|!s.is_empty())).collect::<Vec<_>>();let attempt=if attempts.len()==1{attempts[0]}else{""};let(si,sv)=indexed(&starts,profiles.len());let(fi,fv)=indexed(&finishes,profiles.len());let expected=(0..profiles.len()as i64).collect::<BTreeSet<_>>();let mut profile_valid=!attempt.is_empty()&&sv&&fv&&si.keys().copied().collect::<BTreeSet<_>>()==expected&&fi.keys().copied().collect::<BTreeSet<_>>()==expected;
 if profile_valid{for(i,p)in profiles.iter().enumerate(){let p=p.as_str().unwrap_or("");let a=si[&(i as i64)];let b=fi[&(i as i64)];let plugin=if p.starts_with("builtin:"){!truth(&a["definition_sha256"])&&!truth(&b["definition_sha256"])}else{sha(&a["definition_sha256"])&&a["definition_sha256"]==b["definition_sha256"]&&truth(&a["source_plugin"])&&a["source_plugin"]==b["source_plugin"]};let timing=a["started_monotonic_ms"].as_f64().zip(b["started_monotonic_ms"].as_f64()).zip(b["finished_monotonic_ms"].as_f64()).is_some_and(|((a,b),end)|a==b&&end>=a)&&a["ordinal"].as_u64().zip(b["ordinal"].as_u64()).is_some_and(|(a,b)|a<b);if !(identity(a)==p&&identity(b)==p&&!text(a,"agent_id").is_empty()&&a["agent_id"]==b["agent_id"]&&a["attempt_id"]==attempt&&b["attempt_id"]==attempt&&b["status"]=="completed"&&!truth(&b["error"])&&plugin&&timing){profile_valid=false;break}}}
 let terminal=terminals.len()==1&&terminals[0]["event_type"]=="run_finished"&&terminals[0]["attempt_id"]==attempt&&!["error","failed","cancelled","blocked"].contains(&text(terminals[0],"status"))&&!truth(&terminals[0]["error"]);let pairs=(0..profiles.len()as i64).flat_map(|left|((left+1)..profiles.len()as i64).map(move|right|(left,right))).collect::<BTreeSet<_>>();let mut observed=BTreeMap::new();let mut parallel=true;for item in overlaps{if let Some((left,right))=item["left_dispatch_index"].as_i64().zip(item["right_dispatch_index"].as_i64()){if left>=right||observed.insert((left,right),item).is_some(){parallel=false;}}else{parallel=false;}}if s["require_parallel"]==true{parallel=parallel&&observed.keys().copied().collect::<BTreeSet<_>>()==pairs&&observed.values().all(|v|v["observed"]==true&&v["overlap_ms"].as_f64().is_some_and(|n|n>=25.));}let prompt=o["prompt_sha256"]==sha256(candidate_prompt(s).as_bytes());
 let mut normalized=BTreeMap::<String,Value>::new();let mut arguments=BTreeMap::<String,Value>::new();let mut malformed=false;for item in tool_starts{if !aliases(item,&["tool_call_id","call_id","tool_id"])||!aliases(item,&["name","tool_name"]){malformed=true;}let id=call_id(item);if id.is_empty(){malformed=true;continue}let merged=normalized.entry(id.clone()).or_insert(json!({}));let previous=tool_name(merged);let current=tool_name(item);if !previous.is_empty()&&!current.is_empty()&&previous!=current{malformed=true;}for(k,v)in item.as_object().unwrap(){if v.is_null()||v==""{continue}if k=="ordinal"&&v.as_u64().is_some(){merged[k]=json!(merged[k].as_u64().map(|old|old.min(v.as_u64().unwrap())).unwrap_or(v.as_u64().unwrap()));}else if k=="arguments"{let parsed=if let Some(text)=v.as_str(){match crate::strict_json::parse(text.as_bytes()){Ok(v)=>v,Err(_)=>{malformed=true;continue}}}else{v.clone()};if arguments.get(&id).is_some_and(|old|canonical(old)!=canonical(&parsed)){malformed=true;}else{arguments.insert(id.clone(),parsed.clone());merged[k]=parsed;}}else{merged[k]=v.clone();}}}
 let mut normalized_results=BTreeMap::<String,Vec<&Value>>::new();for item in tool_results{if !aliases(item,&["tool_call_id","call_id","tool_id"])||!aliases(item,&["name","tool_name"]){malformed=true;}let id=call_id(item);if id.is_empty(){malformed=true;continue}if normalized.get(&id).is_none_or(|start|tool_name(item).is_empty()||tool_name(item)!=tool_name(start)){malformed=true;}normalized_results.entry(id).or_default().push(item);}let start_ids=normalized.keys().cloned().collect::<BTreeSet<_>>();let result_ids=normalized_results.keys().cloned().collect::<BTreeSet<_>>();let tool_pairs=!malformed&&start_ids==result_ids;let spawn_ids=normalized.iter().filter(|(_,v)|tool_name(v)=="spawn_subagent").map(|(id,_)|id.clone()).collect::<Vec<_>>();let spawn_id=if spawn_ids.len()==1{spawn_ids[0].as_str()}else{""};let empty=json!({});let spawn=normalized.get(spawn_id).unwrap_or(&empty);let args=&spawn["arguments"];let delegation=normalized_delegation(args);let tasks=delegation.as_ref().map(|v|arr(&v["tasks"])).unwrap_or(&[]);let canonical_args=canonical_delegation(s);let canonical_valid=profiles.is_empty()&&canonical_args.is_none()&&args.is_null()||!profiles.is_empty()&&delegation.as_ref().zip(canonical_args.as_ref()).is_some_and(|(a,b)|canonical(a)==canonical(b)&&s["canonical_delegation"]["canonical_sha256"]==digest(a));let task_identity=|task:&Value|{if !text(task,"agent_id").is_empty(){text(task,"agent_id").to_string()}else if !text(task,"agent_type").is_empty(){format!("builtin:{}",text(task,"agent_type"))}else{String::new()}};let identities=tasks.iter().map(task_identity).collect::<Vec<_>>();let concurrency=if s["require_parallel"]==true{profiles.len()}else{1};let basic=profiles.is_empty()&&spawn_ids.is_empty()||!profiles.is_empty()&&!malformed&&spawn_ids.len()==1&&delegation.as_ref().is_some_and(|v|v["tasks"].is_array()&&v["max_concurrency"].as_u64()==Some(concurrency as u64))&&identities==profiles.iter().map(|p|p.as_str().unwrap_or("").to_string()).collect::<Vec<_>>();let delegation_valid=basic&&canonical_valid;let requirements=arr(&s["delegation_task_requirements"]).iter().filter(|v|v.is_object()).map(|v|(text(v,"agent_id"),v)).collect::<BTreeMap<_,_>>();let mut prompts=profiles.is_empty();if basic&&!profiles.is_empty(){prompts=true;for(p,task)in profiles.iter().zip(tasks){let Some(req)=requirements.get(p.as_str().unwrap_or(""))else{prompts=false;break};let Some(prompt)=task["prompt"].as_str()else{prompts=false;break};let prompt=prompt.trim();let contains=req["prompt_contains_all"].as_array();let excludes=req["prompt_excludes_all"].as_array();if prompt.chars().count()<(req["min_prompt_chars"].as_u64().unwrap_or(0)as usize)||!contains.is_some_and(|a|a.iter().all(|v|v.as_str().is_some_and(|s|prompt.contains(s))))||!excludes.is_some_and(|a|a.iter().all(|v|v.as_str().is_some_and(|s|!prompt.to_lowercase().contains(&s.to_lowercase())))){prompts=false;break}}}
 let spawn_results=normalized_results.get(spawn_id).map(Vec::as_slice).unwrap_or(&[]);let completed=spawn_results.iter().filter(|v|["tool_call_result","tool_call_completed","tool_result"].contains(&text(v,"event_type"))&&tool_name(v)=="spawn_subagent"&&v["success"]==true&&["","completed","succeeded","success"].contains(&text(v,"status"))&&no_error(v)&&["none","read_only"].contains(&text(v,"side_effect_state").to_lowercase().as_str())&&v["ordinal"].as_u64().is_some()).collect::<Vec<_>>();let aggregate=profiles.is_empty()||delegation_valid&&!malformed&&completed.len()==1&&spawn_results.iter().all(|v|v["success"]!=false&&!["error","failed","cancelled","blocked","unknown"].contains(&text(v,"status").to_lowercase().as_str())&&no_error(v)&&["none","read_only"].contains(&text(v,"side_effect_state").to_lowercase().as_str()));let parent_names=normalized.values().map(tool_name).collect::<BTreeSet<_>>();let no_extra=!malformed&&parent_names.iter().all(|n|n=="spawn_subagent")&&if profiles.is_empty(){start_ids.is_empty()}else{start_ids==BTreeSet::from([spawn_id.to_string()])};let terminal_ordinal=if terminals.len()==1{terminals[0]["ordinal"].as_u64()}else{None};let final_text=text_events.iter().filter(|v|v["content_chars"].as_u64().is_some_and(|n|n>0)).filter_map(|v|v["ordinal"].as_u64()).max();let synthesis=terminal&&terminal_ordinal.zip(final_text).is_some_and(|(end,text)|if !profiles.is_empty(){profile_valid&&aggregate&&finishes.iter().filter_map(|v|v["ordinal"].as_u64()).max().zip(completed.first().and_then(|v|v["ordinal"].as_u64())).is_some_and(|(child,aggregate)|child<aggregate&&aggregate<text&&text<end)}else{text<end});
 [("terminal.current-attempt-success",terminal),("prompt.digest-bound",prompt),("delegation.exact-profile-lifecycle",profile_valid),("delegation.parallel-overlap",parallel),("delegation.canonical-task-object",canonical_valid),("delegation.task-prompts",prompts),("tools.start-result-paired",tool_pairs),("tools.delegation-call-observed",delegation_valid),("tools.spawn-aggregate-success",aggregate),("tools.no-extra-parent-side-effects",no_extra),("lifecycle.delegation-synthesis-order",synthesis)].into_iter().map(|(id,passed)|json!({"check_id":id,"passed":passed,"observed_sha256":digest(&json!({"scenario_id":s["scenario_id"],"observation_sha256":o["observation_sha256"],"check_id":id,"passed":passed}))})).collect()
}
#[cfg(test)]mod tests{use super::*;#[test]fn answer_rejects_duplicate_or_multiple_blocks(){assert!(answer_json("<FINAL_JSON>{\"a\":1,\"a\":2}</FINAL_JSON>","final_json_tag").is_err());assert!(answer_json("<FINAL_JSON>{}</FINAL_JSON><FINAL_JSON>{}</FINAL_JSON>","final_json_tag").is_err());}#[test]fn exact_typed_assertion_and_self_assessment(){assert!(!assertion(&json!({"kind":"json_equals","path":"/x","expected":1}),&json!({"x":1.0}),"").unwrap().0);assert!(self_assessment(&json!({"nested":{"score":100}}),""));}#[test]fn missing_runtime_evidence_cannot_accept_valid_answer(){let result=validated_trial(&json!({"scenario_id":"x","required_agent_ids":[],"require_parallel":false,"prompt":"p","expected_assertions":[{"assertion_id":"x","kind":"json_equals","path":"/x","expected":1}]}),&json!({"trial":1,"candidate_output":"<FINAL_JSON>{\"x\":1}</FINAL_JSON>","observation_sha256":"x"})).unwrap();assert_eq!(result["golden_passed"],true);assert_eq!(result["trial_accepted"],false);}}

fn indexed<'a>(receipts:&[&'a Value],count:usize)->(BTreeMap<i64,&'a Value>,bool){let mut map=BTreeMap::new();let mut valid=receipts.len()==count;for receipt in receipts{if let Some(index)=receipt["dispatch_index"].as_i64(){if map.insert(index,*receipt).is_some(){valid=false;}}else{valid=false;}}(map,valid)}
